window.HOEREN_TESTS[59] = {"id":"im-park-und-erholung","name":"Im Park und Erholung","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Park-Besucher: Der Stadtpark hat neue Regeln. Hunde nur an der Leine — überall im Park, nicht nur am Spielplatz. Müll bitte in Eimer, nicht im Gras. Grillen erlaubt, aber nur am Grillplatz hinten. Also nur am Grillplatz hinten, nicht überall im Park. Wir wünschen einen schönen Aufenthalt!","gender":"f","q":"Wo darf man grillen?","opts":["Nur am Grillplatz.","Überall.","Gar nicht."],"correct":0},{"transcript":"Hallo Lisa, hier ist Anna. Das Wetter ist super heute! Lass uns in den Park gehen — Picknick machen. Ich bringe Decke und Brote, du kannst Getränke holen. Nichts mitbringen geht nicht, wir brauchen Getränke. Treffen wir uns am Brunnen um 14 Uhr? Wenn Regen, sage ich Bescheid. Tschüs!","gender":"f","q":"Was bringt Lisa?","opts":["Decke und Brote.","Getränke.","Nichts."],"correct":1},{"transcript":"Achtung Besucher: Der Spielplatz im Park ist wegen Renovierung geschlossen. Bis Juni dauert die Arbeit — neue Schaukeln, neuer Sandkasten. Der Park ist offen und das Café auch, nur der Spielplatz ist zu. Kinder können den anderen Spielplatz im West-Park benutzen. Wir entschuldigen uns für Unannehmlichkeiten. Sicherheit zuerst!","gender":"m","q":"Was ist geschlossen?","opts":["Der Spielplatz.","Das Café.","Der Park."],"correct":0},{"transcript":"Hi Markus, hier ist Tom. Pass auf, ich gehe heute Abend laufen im Park. Nicht spazieren und nicht Fahrrad fahren, wirklich laufen! Möchtest du mit? Ich habe Sportprogramm jeden zweiten Tag. Treffen 18 Uhr am Haupteingang. 5 Kilometer ungefähr. Wenn du nicht magst, ist okay. Aber lass mich wissen. Tschüs!","gender":"m","q":"Was macht Tom?","opts":["Geht spazieren.","Geht laufen.","Geht Fahrrad fahren."],"correct":1},{"transcript":"Liebe Eltern: Im Park startet ab Mai ein Yoga-Kurs für Kinder, jeden Samstag 10 Uhr. Kostenlos, draußen unter Bäumen. Auch Kurs für Erwachsene um 11 Uhr — 10 Euro pro Stunde. Keine 20 Euro, nur 10 Euro pro Stunde für Erwachsene. Bitte mitbringen: Yoga-Matte, Wasser, bequeme Kleidung. Anmeldung nicht nötig!","gender":"f","q":"Was kostet Erwachsenen-Kurs?","opts":["Kostenlos.","20 Euro.","10 Euro."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Was machen sie an welchem Tag? Wählen Sie für jeden Tag einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Der Park ist diese Woche trocken und der Kalender liegt bereit."},{"speaker":"Lisa","gender":"f","text":"Schön, dass wir einen Plan machen. Ich brauche dringend etwas frische Luft."},{"speaker":"Lukas","gender":"m","text":"Eine Runde um den See reicht mir völlig. Ich gehe am Montag joggen."},{"speaker":"Lisa","gender":"f","text":"Dienstag fahre ich Fahrrad am Fluss. Der Weg ist dann schön frei."},{"speaker":"Lukas","gender":"m","text":"Macht jemand bei uns Tai Chi auf dem Rasen?"},{"speaker":"Lisa","gender":"f","text":"Nein. Tai Chi machen wir in dieser Woche nicht."},{"speaker":"Lukas","gender":"m","text":"Tom sucht am Mittwoch die Ruhe. Er liest auf einer Bank ein dickes Buch."},{"speaker":"Lisa","gender":"f","text":"Die Enten bleiben ruhig im Wasser neben ihm."},{"speaker":"Lukas","gender":"m","text":"Die Sonne scheint bis in den späten Nachmittag hinein."},{"speaker":"Lisa","gender":"f","text":"Sara macht am Donnerstag ein Picknick mit Freundinnen. Obst und Saft stehen auf der Decke."},{"speaker":"Lukas","gender":"m","text":"Spielt jemand Frisbee auf der großen Wiese?"},{"speaker":"Lisa","gender":"f","text":"Nein. Frisbee spielen wir auch nicht. Die Scheibe liegt zu Hause im Schrank."},{"speaker":"Lukas","gender":"m","text":"Tim und seine Freunde spielen am Freitag Fußball auf der Wiese."},{"speaker":"Lisa","gender":"f","text":"Die beiden Tore stehen dort schon seit dem Frühling fest."},{"speaker":"Lukas","gender":"m","text":"Dann hänge ich den Zettel an unsere Küchentür."},{"speaker":"Lisa","gender":"f","text":"Ich warte am See auf dich und bringe die Schuhe mit."}],"options":[{"letter":"a","text":"Tai Chi"},{"letter":"b","text":"Fahrrad fahren"},{"letter":"c","text":"Joggen"},{"letter":"d","text":"Picknick mit Freundinnen"},{"letter":"e","text":"Mit Hund Gassi gehen"},{"letter":"f","text":"Frisbee spielen"},{"letter":"g","text":"Fußball spielen"},{"letter":"h","text":"Auf einer Bank lesen"},{"letter":"i","text":"Spazieren"}],"items":[{"person":"Montag","correct":"c"},{"person":"Dienstag","correct":"b"},{"person":"Mittwoch","correct":"h"},{"person":"Donnerstag","correct":"d"},{"person":"Freitag","correct":"g"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Tourist","gender":"m","text":"Entschuldigung, wo ist der See im Park? Ist es weit?"},{"speaker":"Mann","gender":"m","text":"Geradeaus, dann links beim Café. Nicht weit, nur 5 Minuten? Nein, 10 Minuten zu Fuß."},{"speaker":"Tourist","gender":"m","text":"10 Minuten, gut. Und 20 Minuten wäre zu viel für mich."},{"speaker":"Mann","gender":"m","text":"Nein, keine 20 Minuten. Zehn Minuten, ganz gemütlich."},{"speaker":"Tourist","gender":"m","text":"Perfekt, danke! Dann gehe ich los."}],"q":"Wie lange zum See?","opts":["10 Minuten.","5 Minuten.","20 Minuten."],"correct":0},{"lines":[{"speaker":"Vater","gender":"m","text":"Wo ist der Spielplatz? Bei den Schaukeln links?"},{"speaker":"Mutter","gender":"f","text":"Ja, dort. Die Kinder sind da sicher."},{"speaker":"Vater","gender":"m","text":"Ist der Boden hart oder aus Sand?"},{"speaker":"Mutter","gender":"f","text":"Weder hart noch Sand. Weicher Boden und hohe Zäune, keine Sorge."},{"speaker":"Vater","gender":"m","text":"Gut, dann spiele ich mit den Kindern. Wo sind die Bälle? Mama?"}],"q":"Wie ist der Boden?","opts":["Weich.","Hart.","Sand."],"correct":0},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag! Darf ich hier überall Fahrrad fahren?"},{"speaker":"Wächter","gender":"m","text":"Auf den Hauptwegen ja, überall leider nicht."},{"speaker":"Frau","gender":"f","text":"Auch im Gras? Das wäre schön weich."},{"speaker":"Wächter","gender":"m","text":"Nein, im Gras nicht, das ist neu. Nur auf den Wegen, das Gras ist verboten."},{"speaker":"Frau","gender":"f","text":"Verstanden! Nur Wege, kein Gras. Danke und tschüss!"}],"q":"Wo darf sie fahren?","opts":["Überall.","Nur auf Wegen.","Nur im Gras."],"correct":1},{"lines":[{"speaker":"Tochter","gender":"f","text":"Papa, ich habe Hunger, großen Hunger! Was gibt es am Café-Stand?"},{"speaker":"Vater","gender":"m","text":"Eis, Pommes und Wraps. Was möchtest du, mein Schatz?"},{"speaker":"Tochter","gender":"f","text":"Kein Eis heute. Wraps oder Pommes?"},{"speaker":"Vater","gender":"m","text":"Wraps sind leider schon aus heute. Nur noch Pommes und Eis, heute."},{"speaker":"Tochter","gender":"f","text":"Dann Pommes, bitte! Mit viel Ketchup, lecker!"}],"q":"Was möchte Tochter?","opts":["Eis.","Pommes.","Wraps."],"correct":1},{"lines":[{"speaker":"Mann1","gender":"m","text":"Wann sperrt der Park? Im Sommer um 23 Uhr, oder?"},{"speaker":"Wächter","gender":"m","text":"Im Sommer 23 Uhr, im Winter 20 Uhr, genau, so ist es."},{"speaker":"Mann1","gender":"m","text":"Und jetzt im April? Auch 20 Uhr?"},{"speaker":"Wächter","gender":"m","text":"Nein, nicht 20. Im April 21 Uhr, das ist Übergangszeit, im Frühling."},{"speaker":"Mann1","gender":"m","text":"21 Uhr, verstanden! Danke und tschüss! Schönen Abend!"},{"speaker":"Wächter","gender":"m","text":"Gern! Und kommen Sie morgen wieder, bei schönem Wetter!"}],"q":"Wann sperrt der Park im April?","opts":["20 Uhr.","23 Uhr.","21 Uhr."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Walter, einer Park-Direktorin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Walter, was sind Ihre Aufgaben im Park?"},{"speaker":"Walter","gender":"f","text":"Ich kümmere mich um die Pflanzen und die Wege im ganzen Park. Viele Gärtner arbeiten bei mir, im Sommer auch Studenten. Im Winter sind wir weniger Leute."},{"speaker":"Reporter","gender":"m","text":"Wie viele Besucher kommen?"},{"speaker":"Walter","gender":"f","text":"Im Sommer sehr viele, im Winter viel weniger. Bei Regen fast niemand. Aber unser Park ist sehr beliebt bei Familien. Am Sonntag kommen die meisten."},{"speaker":"Reporter","gender":"m","text":"Was sind die Probleme?"},{"speaker":"Walter","gender":"f","text":"Der Müll, ganz klar. Manche Leute werfen alles auf den Boden, Flaschen, Papier, alles. Das ärgert mich wirklich sehr. Wir stellen mehr Eimer auf."},{"speaker":"Reporter","gender":"m","text":"Welche Feste gibt es im Park? Ist im Sommer etwas los?"},{"speaker":"Walter","gender":"f","text":"Im Sommer ein großes Fest mit Musik und Essen, drei Tage lang. Auch ein Lauf geht durch den Park, im September. Alle dürfen mitmachen, auch Kinder."},{"speaker":"Reporter","gender":"m","text":"Wie sehen Sie die Zukunft?"},{"speaker":"Walter","gender":"f","text":"Parks werden immer wichtiger, nicht weniger! Die Stadt braucht Grün. Wir pflanzen jedes Jahr mehr Bäume, etwa hundert. Grün ist gesund für alle, jedes Jahr wieder!"}],"items":[{"q":"Im Sommer und Winter kommen gleich viele Besucher.","correct":"nein"},{"q":"Frau Walter kümmert sich um Pflanzen und Wege.","correct":"ja"},{"q":"Müll ist ein Problem im Park.","correct":"ja"},{"q":"Sie findet, Parks werden in Zukunft weniger wichtig.","correct":"nein"},{"q":"Im Park gibt es im Sommer ein großes Fest.","correct":"ja"}]}]};
